const items = $input.all();
const countryRestrictionPatterns = [
  /\bUS[- ]?only\b/i, /\bUSA?\s+resident/i,
  /\bmust be (authorized|eligible) to work in the (us|united states|uk|eu)\b/i,
  /\bno\s+(h1b|sponsorship|visa sponsorship)\b/i,
  /\b401\(?k\)?\b/i, /\bHSA\b/i, /\beu\s+only\b/i, /\bindia\s+only\b/i,
  /\bpan[- ]india\b/i, /\bcountries of europe or ukraine\b/i,
  /\bmust be based in\b/i, /\brelocat(e|ion) to\b/i,
  /\bwithin \d+ (hours?|hrs?) of (est|pst|cst|gmt)\b/i
];
const seniorityRedFlags = [
  /\bsenior\b/i, /\bstaff\b/i, /\blead\s+(engineer|developer)\b/i,
  /\bprincipal\b/i, /\b(5|6|7|8|9|10)\+?\s*years?\b/i,
  /\bat least (4|5|6|7|8) years?\b/i
];
const degreeRedFlags = [
  /\brequires? a (bachelor|master|phd)('s)? degree\b/i,
  /\bdegree in computer science required\b/i
];
const stackRedFlags = [
  /\bpython\s+(is\s+)?(required|core|primary|expertise)\b/i,
  /\bexpertise in python\b/i, /\bflutter\b/i, /\bdart\b/i
];
function checkFlags(text, patterns) {
  if (!text) return [];
  return patterns.filter(p => p.test(text)).map(p => p.source);
}
function stripBoilerplate(text) {
  if (!text) return text;
  const contentMarkers = [
    /##\s*Description/i,
    /##\s*About the [Rr]ole/i,
    /\[Skip to content\]/i,
    /#\s*Careers at/i
  ];
  let earliestIndex = -1;
  for (const marker of contentMarkers) {
    const match = text.match(marker);
    if (match && match.index !== undefined) {
      if (earliestIndex === -1 || match.index < earliestIndex) {
        earliestIndex = match.index;
      }
    }
  }
  if (earliestIndex > -1) {
    return text.slice(earliestIndex).trim();
  }
  return text;
}
return items.map(item => {
  const rawCombined = item.json.title + ' ' + (item.json.description || '');
  const text = stripBoilerplate(rawCombined);
  const countryFlags = checkFlags(text, countryRestrictionPatterns);
  const seniorityFlags = checkFlags(text, seniorityRedFlags);
  const degreeFlags = checkFlags(text, degreeRedFlags);
  const stackFlags = checkFlags(text, stackRedFlags);
  const totalFlags = countryFlags.length + seniorityFlags.length + degreeFlags.length + stackFlags.length;
  return {
    json: {
      company: item.json.name,
      careersUrl: item.json.careersUrl || item.json.applicationLink || item.json.apply_url || item.json.url || null,
      raw_text: text.slice(0, 8000),
      pre_filter_verdict: totalFlags === 0 ? 'PASSES_KEYWORD_FILTER' : 'FLAGGED',
      flags_found: { country: countryFlags, seniority: seniorityFlags, degree: degreeFlags, stack: stackFlags }
    }
  };
});

const items = $input.all();
const originalData = $('Filter - Red Flag Keywords').all();

return items.map((item) => {
  let parsed;
  try {
    const rawText = item.json.choices?.[0]?.message?.content || '{}';
    parsed = JSON.parse(rawText);
  } catch (e) {
    parsed = { company: 'unknown', verdict: 'PARSE_ERROR', matching_role_title: null, reason: 'OpenAI response was not valid JSON - check manually' };
  }
  // Match by company name instead of array index - safer if item order/count
  // ever differs between nodes.
  const match = originalData.find(d => d.json.company === parsed.company);
  parsed.careersUrl = match?.json?.careersUrl || null;
  return { json: parsed };
});

// Only pass through NEW matches worth reporting.
// Filters out NO_MATCH and PARSE_ERROR so the report only shows real leads.
const items = $input.all();
return items.filter(item => 
  item.json.verdict === 'MATCH' || item.json.verdict === 'UNCLEAR_NEEDS_HUMAN_CHECK'
);

const items = $input.all();
const date = new Date().toISOString().split('T')[0];

let report = `# Wayfind Report - ${date}\n\n`;
report += `${items.length} potential match(es) found this run.\n\n`;

items.forEach(item => {
  const j = item.json;
  report += `## ${j.company}\n`;
  report += `- **Verdict:** ${j.verdict}\n`;
  report += `- **Role:** ${j.matching_role_title || 'not specified'}\n`;
  report += `- **Apply:** ${j.careersUrl || 'link not available'}\n`;
  report += `- **Reason:** ${j.reason}\n\n`;
});

if (items.length === 0) {
  report += 'No new matches this run.\n';
}

return [{ json: { report_markdown: report, date } }];

const allInput = $input.all();
let remoteOkJobs = [];
let remotiveJobs = [];
let himalayasJobs = [];

for (const item of allInput) {
  const data = item.json;
  if (data.company) {
    remoteOkJobs.push(data);
  } else if (data.jobs && Array.isArray(data.jobs)) {
    const firstJob = data.jobs[0] || {};
    if (firstJob.companyName !== undefined) {
      himalayasJobs = data.jobs;
    } else {
      remotiveJobs = data.jobs;
    }
  }
}

function titleOk(title) {
  const t = (title || '').toLowerCase();
  const senior = /senior|staff|lead|principal|director|manager/.test(t);
  const relevant = /engineer|developer|full.?stack|frontend|backend/.test(t);
  return !senior && relevant;
}

const fromRemoteOk = remoteOkJobs
  .filter(job => job.company && (!job.location || job.location.trim() === '') && titleOk(job.position))
  .map(job => ({ json: { name: job.company, careersUrl: job.apply_url, title: job.position, description: job.description || '' } }));

const fromRemotive = remotiveJobs
  .filter(job => titleOk(job.title))
  .map(job => ({ json: { name: job.company_name, careersUrl: job.url, title: job.title, description: job.description || '' } }));

const fromHimalayas = himalayasJobs
  .filter(job => titleOk(job.title))
  .map(job => ({
    json: {
      name: job.companyName || 'Unknown (Himalayas)',
      careersUrl: job.companySlug
        ? `https://himalayas.app/companies/${job.companySlug}`
        : `https://himalayas.app/jobs?q=${encodeURIComponent(job.companyName || job.title)}`,
      title: job.title,
      description: job.excerpt || ''
    }
  }));

return [...fromRemoteOk, ...fromRemotive, ...fromHimalayas];

const newJobs = $('Filter Real Jobs').all();
const alreadyChecked = $input.all().map(item => item.json.company);

const filtered = newJobs.filter(job => !alreadyChecked.includes(job.json.name));
return filtered;
